<?php
// Street Food Online Ordering System. PHP 8 / MySQL. Local classroom demo.
// XAMPP default: root user, empty password, port 3306. Edit if yours differs.
$host=getenv('SF_HOST')?:'127.0.0.1';$port=getenv('SF_PORT')?:'3306';
$user=getenv('SF_USER')?:'root';$password=getenv('SF_PASS')?:'';
date_default_timezone_set('Asia/Kolkata');
ini_set('session.use_strict_mode','1');session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax']);session_start();
$_SESSION['csrf']=$_SESSION['csrf']??bin2hex(random_bytes(32));
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function cash($n){return 'Rs '.number_format((float)$n,2);}
function cents($n){return (int)round((float)$n*100);}
function q($sql,$a=[]){global $db;$s=$db->prepare($sql);$s->execute($a);return $s;}
function jump($p){header('Location: ?page='.$p);exit;}
function tok(){echo '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">';}
function val($n){return trim((string)($_POST[$n]??''));}
function owner(){return !empty($_SESSION['owner']);}
function guard(){if(!owner())jump('login');}
function notify($s){$_SESSION['notice']=$s;}
function ph($s){$s=preg_replace('/[\s()+-]/','',$s);if(!preg_match('/^[0-9]{10,15}$/',$s))throw new Exception('Use a phone number with 10 to 15 digits.');return $s;}
function basket(){ $rows=[];foreach(($_SESSION['cart']??[])as$id=>$qty){$r=q('SELECT m.*,c.name category FROM menu_items m JOIN categories c ON c.id=m.category_id WHERE m.id=?',[$id])->fetch();if($r){$r['qty']=$qty;$r['subtotal']=cents($r['price'])*$qty/100;$rows[]=$r;}}return $rows;}
function nextStates($o){return ['Placed'=>['Accepted','Cancelled'],'Accepted'=>['Preparing','Cancelled'],'Preparing'=>['Ready','Cancelled'],'Ready'=>$o['fulfilment']==='Delivery'?['Out for delivery','Cancelled']:['Completed','Cancelled'],'Out for delivery'=>['Completed','Cancelled'],'Completed'=>[],'Cancelled'=>[]][$o['status']];}
$schema=<<<'SQL'
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS menu_items(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NOT NULL,name VARCHAR(100) NOT NULL,description VARCHAR(250) NOT NULL,price DECIMAL(10,2) NOT NULL,available TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(category_id) REFERENCES categories(id),CHECK(price>0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(15) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,order_code CHAR(12) NOT NULL UNIQUE,customer_id INT NOT NULL,customer_name VARCHAR(100) NOT NULL,customer_phone VARCHAR(15) NOT NULL,fulfilment ENUM('Pickup','Delivery') NOT NULL,address VARCHAR(500) NOT NULL DEFAULT '',notes VARCHAR(250) NOT NULL DEFAULT '',status ENUM('Placed','Accepted','Preparing','Ready','Out for delivery','Completed','Cancelled') NOT NULL DEFAULT 'Placed',total DECIMAL(10,2) NOT NULL,payment_method VARCHAR(40) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(customer_id) REFERENCES customers(id),INDEX(created_at),CHECK(total>0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,menu_item_id INT NOT NULL,item_name VARCHAR(100) NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(menu_item_id) REFERENCES menu_items(id),CHECK(quantity>0),CHECK(unit_price>0)) ENGINE=InnoDB;
SQL;
$page=$_GET['page']??'menu';$err='';$fatal=false;$setup=false;$found=null;
try{
$db=new PDO("mysql:host=$host;port=$port;charset=utf8mb4",$user,$password,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
$exists=q("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='street_food_online' AND table_name='admins'")->fetchColumn();
if($exists){$db->exec('USE street_food_online');$setup=!q('SELECT COUNT(*) FROM admins')->fetchColumn();}else $setup=true;
if($_SERVER['REQUEST_METHOD']==='POST'){
if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??''))throw new Exception('Form expired. Refresh the page and try again.');$a=val('action');
if($setup){
 if($a!=='setup')throw new Exception('Set up the database first.');$u=val('username');$pw=val('password');
 if(!preg_match('/^[a-zA-Z0-9_]{3,40}$/',$u)||strlen($pw)<8)throw new Exception('Use 3 to 40 letters/numbers for the username and at least 8 characters for the password.');
 $db->exec('CREATE DATABASE IF NOT EXISTS street_food_online CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$db->exec('USE street_food_online');foreach(explode(';',$schema)as$s)if(trim($s))$db->exec($s);$db->beginTransaction();
 q('INSERT INTO admins(username,password_hash) VALUES(?,?)',[$u,password_hash($pw,PASSWORD_DEFAULT)]);
 foreach(['Chaat','Pav & snacks','South Indian','Drinks']as$c)q('INSERT IGNORE INTO categories(name) VALUES(?)',[$c]);
 if(!q('SELECT COUNT(*) FROM menu_items')->fetchColumn())foreach([
 ['Chaat','Pani puri','Six crisp puris with spicy water and potato.',35],['Chaat','Sev puri','Puris, potato, chutneys and crunchy sev.',50],['Chaat','Bhel puri','Puffed rice with vegetables and tangy chutneys.',45],['Pav & snacks','Vada pav','Potato vada, chutney and a soft pav.',30],['Pav & snacks','Pav bhaji','Spiced vegetable bhaji with two buttered pav.',90],['Pav & snacks','Samosa','Two samosas with mint and tamarind chutneys.',35],['South Indian','Masala dosa','Crisp dosa, potato filling, sambar and chutney.',80],['South Indian','Idli sambar','Three steamed idlis with sambar and chutney.',60],['Drinks','Sweet lassi','A chilled, sweet yogurt drink.',50],['Drinks','Fresh lime soda','Refreshing lime soda, sweet or salted.',35]
 ]as$i)q('INSERT INTO menu_items(category_id,name,description,price) SELECT id,?,?,? FROM categories WHERE name=?',[$i[1],$i[2],$i[3],$i[0]]);
 $db->commit();notify('Shop ready. Sample menu included; customers and orders start empty.');jump('menu');
}
if($a==='login'){
 $_SESSION['tries']=array_filter($_SESSION['tries']??[],fn($t)=>$t>time()-300);if(count($_SESSION['tries'])>=8)throw new Exception('Too many attempts in this browser. Wait five minutes.');$u=q('SELECT * FROM admins WHERE username=?',[val('username')])->fetch();
 if(!$u||!password_verify(val('password'),$u['password_hash'])){$_SESSION['tries'][]=time();throw new Exception('Incorrect username or password.');}session_regenerate_id(true);$_SESSION['owner']=$u['id'];$_SESSION['tries']=[];jump('admin');
}elseif($a==='logout'){unset($_SESSION['owner']);session_regenerate_id(true);jump('menu');
}elseif($a==='add'){
 $id=(int)val('id');$i=q('SELECT * FROM menu_items WHERE id=? AND available=1',[$id])->fetch();if(!$i)throw new Exception('This item is unavailable.');$n=($_SESSION['cart'][$id]??0)+1;if($n>20)throw new Exception('Maximum 20 per item.');$_SESSION['cart'][$id]=$n;notify($i['name'].' added to cart.');jump('menu&category='.(int)($_POST['category']??0));
}elseif($a==='cart'){
 foreach($_POST['qty']??[]as$id=>$n){$n=filter_var($n,FILTER_VALIDATE_INT);if($n===false||$n<0||$n>20)throw new Exception('Use whole quantities from 0 to 20.');if(isset($_SESSION['cart'][(int)$id])){if($n)$_SESSION['cart'][(int)$id]=$n;else unset($_SESSION['cart'][(int)$id]);}}notify('Cart updated.');jump('cart');
}elseif($a==='checkout'){
 $name=val('name');$p=ph(val('phone'));$mode=val('fulfilment');$ad=val('address');$notes=val('notes');
 if(strlen($name)<2||strlen($name)>100||strlen($ad)>500||strlen($notes)>250)throw new Exception('Check name, address and instructions length.');if(!in_array($mode,['Pickup','Delivery']))throw new Exception('Choose pickup or delivery.');if($mode==='Delivery'&&strlen($ad)<10)throw new Exception('Enter a complete delivery address.');
 if(!val('nonce')||!hash_equals($_SESSION['nonce']??'',val('nonce')))throw new Exception('Checkout already submitted or expired. Check confirmation before ordering again.');if(empty($_SESSION['cart']))throw new Exception('Cart is empty.');
 $db->beginTransaction();$rows=[];$total=0;foreach($_SESSION['cart']as$id=>$n){$i=q('SELECT * FROM menu_items WHERE id=? FOR UPDATE',[$id])->fetch();if(!$i||!$i['available'])throw new Exception('A cart item is unavailable. Remove it before checkout.');$i['qty']=$n;$rows[]=$i;$total+=cents($i['price'])*$n;}
 q('INSERT INTO customers(name,phone) VALUES(?,?) ON DUPLICATE KEY UPDATE name=VALUES(name)',[$name,$p]);$cid=q('SELECT id FROM customers WHERE phone=?',[$p])->fetchColumn();$code=strtoupper(bin2hex(random_bytes(6)));$now=date('Y-m-d H:i:s');
 q('INSERT INTO orders(order_code,customer_id,customer_name,customer_phone,fulfilment,address,notes,total,payment_method,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$code,$cid,$name,$p,$mode,$mode==='Delivery'?$ad:'',$notes,number_format($total/100,2,'.',''),$mode==='Delivery'?'Cash on delivery':'Pay at pickup',$now,$now]);$oid=$db->lastInsertId();
 foreach($rows as$i)q('INSERT INTO order_items(order_id,menu_item_id,item_name,quantity,unit_price) VALUES(?,?,?,?,?)',[$oid,$i['id'],$i['name'],$i['qty'],$i['price']]);$db->commit();$_SESSION['last']=$oid;unset($_SESSION['cart'],$_SESSION['nonce']);jump('confirmation');
}elseif($a==='track'){
 $found=q('SELECT * FROM orders WHERE order_code=? AND customer_phone=?',[strtoupper(val('code')),ph(val('phone'))])->fetch();if(!$found)throw new Exception('No matching order. Check both code and phone.');$page='track';
}elseif(in_array($a,['save','toggle','status'])){
 guard();$id=(int)val('id');
 if($a==='save'){
 $name=val('name');$desc=val('description');$price=val('price');$cat=(int)val('category_id');if(strlen($name)<2||strlen($name)>100||strlen($desc)>250||!preg_match('/^[0-9]{1,5}(\.[0-9]{1,2})?$/',$price)||cents($price)<=0||!q('SELECT id FROM categories WHERE id=?',[$cat])->fetchColumn())throw new Exception('Check name, category, description and price (Rs 0.01 to 99999.99).');
 if($id)q('UPDATE menu_items SET category_id=?,name=?,description=?,price=? WHERE id=?',[$cat,$name,$desc,$price,$id]);else q('INSERT INTO menu_items(category_id,name,description,price) VALUES(?,?,?,?)',[$cat,$name,$desc,$price]);notify('Item saved.');jump('manage');
 }elseif($a==='toggle'){q('UPDATE menu_items SET available=1-available WHERE id=?',[$id]);notify('Availability updated.');jump('manage');}
 else{$db->beginTransaction();$o=q('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id])->fetch();if(!$o||!in_array(val('status'),nextStates($o)))throw new Exception('Invalid status change. Refresh orders.');q('UPDATE orders SET status=?,updated_at=? WHERE id=?',[val('status'),date('Y-m-d H:i:s'),$id]);$db->commit();notify('Status updated.');jump('admin');}
}else throw new Exception('Unknown action.');
}
}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();if($e instanceof PDOException){$fatal=true;$err='Database error. Start MySQL and check the connection settings at the top of index.php. '.$e->getMessage();}else $err=$e->getMessage();}
if(!$fatal&&!$setup&&in_array($page,['admin','manage','sales','database']))guard();
if(!$fatal&&!$setup&&$page==='checkout'&&!basket())jump('cart');
$cats=(!$fatal&&!$setup)?q('SELECT * FROM categories ORDER BY id')->fetchAll():[];
function receipt($o){echo '<div class="receipt"><div><small>ORDER CODE</small><h2>'.h($o['order_code']).'</h2></div><span class="badge">'.h($o['status']).'</span></div><div class="facts">';foreach(['Customer'=>$o['customer_name'],'Order type'=>$o['fulfilment'],'Payment'=>$o['payment_method'],'Placed (IST)'=>$o['created_at']]as$k=>$v)echo '<div><small>'.h($k).'</small><b>'.h($v).'</b></div>';echo '</div>';if($o['address'])echo '<p><b>Address:</b> '.h($o['address']).'</p>';if($o['notes'])echo '<p><b>Instructions:</b> '.h($o['notes']).'</p>';echo '<table><tr><th>Item</th><th>Qty</th><th>Unit price</th><th>Subtotal</th></tr>';foreach(q('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll()as$i)echo '<tr><td>'.h($i['item_name']).'</td><td>'.$i['quantity'].'</td><td>'.cash($i['unit_price']).'</td><td>'.cash(cents($i['unit_price'])*$i['quantity']/100).'</td></tr>';echo '</table><div class="total">Total <b>'.cash($o['total']).'</b></div>';}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Street Food Online Ordering System</title><style>
:root{--ink:#251f21;--muted:#585254;--teal:#2d7160;--sand:#f4efec;--line:#eae9ea}*{box-sizing:border-box}body{margin:0;background:var(--sand);color:var(--ink);font:15px/1.5 Arial,sans-serif}header{background:white;border-bottom:1px solid var(--line)}.bar{max-width:1180px;margin:auto;padding:20px 28px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{font-size:22px;font-weight:800;color:var(--ink);text-decoration:none}.brand small{display:block;font-size:11px;font-weight:normal;letter-spacing:1.6px;color:var(--muted)}nav{display:flex;gap:8px;align-items:center;flex-wrap:wrap}nav a{padding:8px 12px;text-decoration:none;color:var(--ink);border-radius:6px}nav a.active{background:#e3eee8;color:var(--teal);font-weight:bold}main{max-width:1180px;margin:auto;padding:30px 28px 50px}h1{font:38px/1.12 Georgia,serif;letter-spacing:-1px;margin:8px 0 14px}h2{font:25px/1.2 Georgia,serif;margin:0 0 18px}h3{font-size:18px;margin:0 0 8px}p{margin:8px 0 16px}.muted,small{color:var(--muted)}.eyebrow{font-size:11px;font-weight:bold;letter-spacing:1.5px;color:var(--teal)}.hero{padding:32px;background:white;border-radius:18px;display:grid;grid-template-columns:1fr 280px;gap:24px;margin-bottom:24px}.hero p{max-width:570px}.aside{background:#f8f2e3;border-radius:14px;padding:24px;display:flex;flex-direction:column;justify-content:center}.aside b{font:25px Georgia,serif}.aside span{color:var(--muted);font-size:13px;margin-top:8px}.chips{display:flex;gap:10px;margin-bottom:22px;flex-wrap:wrap}.chip{padding:8px 16px;background:white;border:1px solid var(--line);border-radius:24px;text-decoration:none;color:var(--ink)}.chip.on{background:var(--teal);color:white;border-color:var(--teal)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card,.panel{background:white;border-radius:14px;padding:24px;border:1px solid var(--line)}.card{display:flex;flex-direction:column}.icon{height:58px;width:58px;display:grid;place-items:center;border-radius:14px;background:#faf2dc;font-size:17px;font-weight:bold;color:var(--teal);margin-bottom:18px}.card p{font-size:14px;min-height:44px;color:var(--muted)}.bottom{margin-top:auto;display:flex;align-items:center;justify-content:space-between}.price{color:var(--teal);font-weight:bold;font-size:18px}button,.button{background:var(--teal);color:white;border:0;border-radius:6px;padding:10px 17px;font:600 14px Arial;cursor:pointer;display:inline-block;text-decoration:none}button:hover,.button:hover{background:#235648}.secondary{background:#ece8e5;color:var(--ink)}.secondary:hover{background:#dfd8d3}.smallbtn{padding:7px 10px;font-size:12px}label{font-size:13px;font-weight:600;display:block;margin:14px 0 6px}input,select,textarea{padding:11px 12px;border:1px solid #d1cbc7;border-radius:6px;font:15px Arial;width:100%;background:white;color:var(--ink)}textarea{resize:vertical}input.qty{width:75px}input:focus,textarea:focus,select:focus{outline:2px solid #aacabe;outline-offset:1px}.narrow{max-width:700px;margin:auto}.cols{display:grid;grid-template-columns:1.15fr .85fr;gap:22px}.notice{padding:13px 18px;margin-bottom:22px;background:#e1eee6;border-radius:8px;color:#235648}.error{background:#fce8e6;color:#9d2424}.warning{background:#faf2dc;padding:12px 16px;border-radius:8px;font-size:13px;color:var(--muted)}table{width:100%;border-collapse:collapse;font-size:14px}th{text-align:left;color:var(--muted);font-size:12px;background:#faf8f6}th,td{padding:12px 10px;border-bottom:1px solid var(--line);vertical-align:top}td:last-child,th:last-child{text-align:right}.table-wrap{overflow:auto}.total{display:flex;justify-content:space-between;align-items:center;padding:20px 0;font-size:19px}.total b{color:var(--teal)}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:18px}.facts{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;background:#faf8f6;padding:18px;border-radius:10px;margin:14px 0}.facts small,.facts b{display:block}.facts b{font-size:14px;margin-top:5px}.badge{display:inline-block;background:#e3eee8;color:var(--teal);border-radius:20px;padding:6px 12px;font-size:12px;font-weight:bold;white-space:nowrap}.receipt{display:flex;justify-content:space-between;align-items:center}.receipt h2{font-family:Arial;font-size:23px;letter-spacing:1px;margin:4px 0 0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:22px 0}.stat{background:white;border:1px solid var(--line);border-radius:12px;padding:20px}.stat b{display:block;font-size:28px;color:var(--teal);margin-top:7px}.order{margin-bottom:18px}.order-head{display:flex;justify-content:space-between;gap:10px}.inline{display:flex;gap:8px;align-items:center}.inline select{width:auto;max-width:190px}.empty{text-align:center;padding:50px}footer{text-align:center;padding:22px;color:var(--muted);font-size:12px;border-top:1px solid #ddd6d2}.subnav{margin:0 0 24px;border-bottom:1px solid #ddd6d2;padding-bottom:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#faf8f6;padding:15px;font-size:12px}details summary{cursor:pointer;font-weight:bold}.dim{opacity:.7}@media(max-width:800px){.bar{align-items:flex-start;flex-direction:column;padding:16px}.hero{grid-template-columns:1fr;padding:24px}.aside{display:none}.grid{grid-template-columns:repeat(2,1fr)}main{padding:22px 16px}.cols{grid-template-columns:1fr}.facts,.stats{grid-template-columns:repeat(2,1fr)}h1{font-size:32px}}@media(max-width:480px){.grid{grid-template-columns:1fr}.order-head{flex-direction:column}.bar nav{gap:0}nav a{padding:7px 9px}.panel{padding:18px}}
</style></head><body><header><div class="bar"><a class="brand" href="?page=menu">Street Food Kitchen<small>ONE SHOP. ALL YOUR STREET FOOD FAVOURITES.</small></a><nav><?php foreach(['menu'=>'Menu','cart'=>'Cart ('.array_sum($_SESSION['cart']??[]).')','track'=>'Track order',owner()?'admin':'login'=>owner()?'Owner dashboard':'Owner login']as$k=>$v):?><a href="?page=<?=$k?>" class="<?=$page===$k?'active':''?>"><?=h($v)?></a><?php endforeach;?></nav></div></header><main>
<?php if($err):?><div class="notice error" role="alert"><?=h($err)?></div><?php endif;if(isset($_SESSION['notice'])):?><div class="notice" role="status"><?=h($_SESSION['notice'])?></div><?php unset($_SESSION['notice']);endif;?>
<?php if($fatal):?><div class="panel"><h1>Start MySQL to open the shop</h1><p>Check the connection settings at the top of index.php, then reload.</p></div>
<?php elseif($setup):?><div class="narrow panel"><span class="eyebrow">FIRST RUN</span><h1>Set up your shop</h1><p>Create the <b>street_food_online</b> database, six tables and a sample menu. Choose your own owner login. Customers and orders start empty.</p><form method="post"><?php tok();?><input type="hidden" name="action" value="setup"><label>Owner username</label><input name="username" required minlength="3" maxlength="40"><label>Owner password</label><input name="password" type="password" required minlength="8" autocomplete="new-password"><p class="muted">At least 8 characters. Keep your chosen login for the owner pages.</p><button>Create database & open shop</button></form><p class="warning">Local college demo only. No real shop receives these orders.</p></div>
<?php elseif($page==='menu'): $cat=(int)($_GET['category']??0);?>
<section class="hero"><div><span class="eyebrow">STREET FOOD ONLINE ORDERING SYSTEM</span><h1>Your street food favourites,<br>all in one place.</h1><p class="muted">Chaat, pav, dosa and a chilled drink. Browse our menu, build your cart and choose pickup or delivery.</p><span class="badge">One shop · Freshly prepared · Cash payment</span></div><div class="aside"><b>Good food.<br>No waiting in line.</b><span>Order here. Follow the status online.<br>Pay at pickup or on delivery.</span></div></section><div class="chips"><a class="chip <?=$cat===0?'on':''?>" href="?page=menu">All items</a><?php foreach($cats as$c):?><a class="chip <?=$cat===(int)$c['id']?'on':''?>" href="?page=menu&category=<?=$c['id']?>"><?=h($c['name'])?></a><?php endforeach;?></div><div class="grid">
<?php $items=q('SELECT m.*,c.name category FROM menu_items m JOIN categories c ON c.id=m.category_id WHERE available=1'.($cat?' AND category_id=?':'').' ORDER BY m.id',$cat?[$cat]:[])->fetchAll();foreach($items as$i):?><article class="card"><div class="icon" aria-hidden="true"><?=['Chaat'=>'CH','Pav & snacks'=>'PV','South Indian'=>'SI','Drinks'=>'DR'][$i['category']]??'SF'?></div><small><?=h($i['category'])?></small><h3><?=h($i['name'])?></h3><p><?=h($i['description'])?></p><div class="bottom"><span class="price"><?=cash($i['price'])?></span><form method="post"><?php tok();?><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?=$i['id']?>"><input type="hidden" name="category" value="<?=$cat?>"><button>Add +</button></form></div></article><?php endforeach;if(!$items):?><div class="panel">No available items in this category.</div><?php endif;?></div>
<?php elseif($page==='cart'): $rows=basket();?><span class="eyebrow">YOUR ORDER</span><h1>Your cart</h1><div class="panel"><?php if(!$rows):?><div class="empty"><h2>Your cart is empty</h2><p>Pick something from the menu to get started.</p><a class="button" href="?page=menu">Browse menu</a></div><?php else:?><form method="post"><?php tok();?><input type="hidden" name="action" value="cart"><div class="table-wrap"><table><tr><th>Item</th><th>Unit price</th><th>Quantity</th><th>Subtotal</th></tr><?php foreach($rows as$i):?><tr><td><b><?=h($i['name'])?></b><br><small><?=h($i['category'])?><?=$i['available']?'':' · Unavailable - set quantity to 0'?></small></td><td><?=cash($i['price'])?></td><td><input aria-label="Quantity for <?=h($i['name'])?>" class="qty" type="number" name="qty[<?=$i['id']?>]" min="0" max="20" value="<?=$i['qty']?>"></td><td><?=cash($i['subtotal'])?></td></tr><?php endforeach;?></table></div><div class="total">Order total<b><?=cash(array_sum(array_column($rows,'subtotal')))?></b></div><small>Set quantity to 0 to remove an item. Click Update cart after changing quantities. Prices are rechecked at checkout.</small><div class="actions"><button class="secondary">Update cart</button><a class="button" href="?page=checkout">Continue to checkout</a><a href="?page=menu">Add more items</a></div></form><?php endif;?></div>
<?php elseif($page==='checkout'): $rows=basket();$sum=array_sum(array_column($rows,'subtotal'));$_SESSION['nonce']=$_SESSION['nonce']??bin2hex(random_bytes(24));?><span class="eyebrow">ALMOST THERE</span><h1>Checkout</h1><div class="cols"><div class="panel"><h2>Your details</h2><form method="post"><?php tok();?><input type="hidden" name="action" value="checkout"><input type="hidden" name="nonce" value="<?=h($_SESSION['nonce'])?>"><label>Name</label><input name="name" required minlength="2" maxlength="100" value="<?=h($_POST['name']??'')?>"><label>Phone number</label><input name="phone" type="tel" required maxlength="20" value="<?=h($_POST['phone']??'')?>"><label>Pickup or delivery</label><select name="fulfilment" onchange="document.getElementById('address').required=this.value==='Delivery'"><?php foreach(['Pickup','Delivery']as$s):?><option <?=($_POST['fulfilment']??'')===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><label>Delivery address (required for delivery)</label><textarea id="address" name="address" rows="3" maxlength="500"><?=h($_POST['address']??'')?></textarea><label>Special instructions (optional)</label><input name="notes" maxlength="250" value="<?=h($_POST['notes']??'')?>"><p class="warning">College demo: pay at pickup / cash on delivery. No online payment, delivery fee or real fulfilment. Menu prices are final demo prices.</p><button>Place order · <?=cash($sum)?></button></form></div><div class="panel"><h2>Order summary</h2><table><tr><th>Item</th><th>Subtotal</th></tr><?php foreach($rows as$i):?><tr><td><?=h($i['name'])?> <small>× <?=$i['qty']?></small></td><td><?=cash($i['subtotal'])?></td></tr><?php endforeach;?></table><div class="total">Total <b><?=cash($sum)?></b></div><a href="?page=cart">Edit cart</a><p class="muted">Menu items, customers and confirmed orders are saved in MySQL. The cart is temporary.</p></div></div>
<?php elseif($page==='confirmation'): $o=q('SELECT * FROM orders WHERE id=?',[$_SESSION['last']??0])->fetch();?><div class="narrow panel"><?php if($o):?><span class="eyebrow">SAVED IN MYSQL</span><h1>Order placed!</h1><p class="muted">Keep the order code. Use it with your phone number to check the status from any browser.</p><?php receipt($o);?><div class="actions"><a class="button" href="?page=track">Track this order</a><a class="button secondary" href="?page=menu">Back to menu</a></div><p class="warning">Local project demo, not an order sent to a real shop.</p><?php else:?><h2>No recent order in this browser</h2><a href="?page=track">Track with code and phone</a><?php endif;?></div>
<?php elseif($page==='track'):?><div class="narrow"><span class="eyebrow">CHECK YOUR ORDER</span><h1>Order status</h1><div class="panel"><form method="post"><?php tok();?><input type="hidden" name="action" value="track"><label>Order code</label><input name="code" required maxlength="12" placeholder="12-character code" value="<?=h($_POST['code']??'')?>"><label>Phone used for this order</label><input name="phone" type="tel" required maxlength="20" value="<?=h($_POST['phone']??'')?>"><div class="actions"><button>Find my order</button></div></form></div><?php if($found):?><div class="panel" style="margin-top:20px"><?php receipt($found);?><p class="muted">Last updated: <?=h($found['updated_at'])?> IST. Submit again to refresh.</p></div><?php endif;?></div>
<?php elseif($page==='login'):?><div class="narrow panel"><span class="eyebrow">OWNER ACCESS</span><h1>Welcome back</h1><p class="muted">Manage your menu, incoming orders and daily sales.</p><form method="post"><?php tok();?><input type="hidden" name="action" value="login"><label>Username</label><input name="username" required autocomplete="username"><label>Password</label><input name="password" type="password" required autocomplete="current-password"><div class="actions"><button>Sign in</button></div></form><p class="warning">Use the owner login you chose on the first-run setup page.</p></div>
<?php elseif(in_array($page,['admin','manage','sales','database'])):?>
<nav class="subnav"><?php foreach(['admin'=>'Orders','manage'=>'Manage menu','sales'=>'Daily sales','database'=>'Database proof']as$k=>$v):?><a class="<?=$page===$k?'active':''?>" href="?page=<?=$k?>"><?=$v?></a><?php endforeach;?><form method="post"><?php tok();?><input type="hidden" name="action" value="logout"><button class="secondary smallbtn">Sign out</button></form></nav>
<?php if($page==='admin'): $start=date('Y-m-d').' 00:00:00';$end=date('Y-m-d',strtotime('+1 day')).' 00:00:00';$s=q("SELECT COUNT(*) n,COALESCE(SUM(status NOT IN ('Completed','Cancelled')),0) active,COALESCE(SUM(status='Completed'),0) done,COALESCE(SUM(CASE WHEN status='Completed' THEN total ELSE 0 END),0) revenue FROM orders WHERE created_at>=? AND created_at<?",[$start,$end])->fetch();?>
<span class="eyebrow">OWNER DASHBOARD</span><h1>Today's kitchen, at a glance.</h1><p class="muted"><?=date('d M Y')?> · Totals use the order placement date (IST).</p><div class="stats"><?php foreach(['Orders today'=>$s['n'],'Active today'=>$s['active'],'Completed today'=>$s['done'],'Completed sales'=>cash($s['revenue'])]as$k=>$v):?><div class="stat"><?=h($k)?><b><?=h($v)?></b></div><?php endforeach;?></div><h2>Latest orders</h2><p class="muted">Latest 50 orders, including earlier days. Advance orders through the kitchen or cancel them.</p>
<?php $orders=q('SELECT * FROM orders ORDER BY id DESC LIMIT 50')->fetchAll();foreach($orders as$o):?><div class="panel order"><div class="order-head"><div><h3><?=h($o['order_code'])?> <span class="badge"><?=h($o['status'])?></span></h3><p><?=h($o['customer_name'])?> · <?=h($o['customer_phone'])?> · <?=h($o['fulfilment'])?><br><small><?=h($o['created_at'])?> IST</small></p></div><b class="price"><?=cash($o['total'])?></b></div><p><?php foreach(q('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll()as$i)echo h($i['item_name']).' × '.$i['quantity'].' &nbsp; ';?></p><?php if($o['address']):?><p><b>Address:</b> <?=h($o['address'])?></p><?php endif;if($o['notes']):?><p><b>Instructions:</b> <?=h($o['notes'])?></p><?php endif;if(nextStates($o)):?><form method="post" class="inline"><?php tok();?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" aria-label="Next status for <?=h($o['order_code'])?>"><?php foreach(nextStates($o)as$n):?><option><?=h($n)?></option><?php endforeach;?></select><button class="smallbtn">Update status</button></form><?php else:?><small>Final status. No further changes.</small><?php endif;?></div><?php endforeach;if(!$orders):?><div class="panel empty">No orders yet. Place a demo order from the customer menu.</div><?php endif;?>
<?php elseif($page==='manage'): $edit=isset($_GET['edit'])?q('SELECT * FROM menu_items WHERE id=?',[(int)$_GET['edit']])->fetch():false;?>
<span class="eyebrow">OWNER MENU</span><h1>Manage menu items</h1><div class="cols"><div class="panel"><h2><?=$edit?'Edit item':'Add a new item'?></h2><form method="post"><?php tok();?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Name</label><input name="name" required minlength="2" maxlength="100" value="<?=h($edit['name']??'')?>"><label>Category</label><select name="category_id"><?php foreach($cats as$c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??0)===$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select><label>Description</label><textarea name="description" maxlength="250"><?=h($edit['description']??'')?></textarea><label>Price (Rs)</label><input name="price" type="number" required min="0.01" max="99999.99" step="0.01" value="<?=h($edit['price']??'')?>"><div class="actions"><button>Save item</button><?php if($edit):?><a href="?page=manage">Cancel edit</a><?php endif;?></div></form></div><div class="panel"><h2>Shop menu</h2><p class="muted">Hide instead of delete. Old order items and their prices stay intact.</p><div class="table-wrap"><table><tr><th>Item</th><th>Price</th><th>Actions</th></tr><?php foreach(q('SELECT m.*,c.name category FROM menu_items m JOIN categories c ON c.id=m.category_id ORDER BY m.id')->fetchAll()as$i):?><tr class="<?=$i['available']?'':'dim'?>"><td><b><?=h($i['name'])?></b><br><small><?=h($i['category'])?> · <?=$i['available']?'Available':'Hidden'?></small></td><td><?=cash($i['price'])?></td><td><a href="?page=manage&edit=<?=$i['id']?>">Edit</a><form method="post" style="margin-top:6px"><?php tok();?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="secondary smallbtn"><?=$i['available']?'Hide':'Show'?></button></form></td></tr><?php endforeach;?></table></div></div></div>
<?php elseif($page==='sales'): $day=$_GET['day']??date('Y-m-d');$d=DateTime::createFromFormat('!Y-m-d',$day);if(!$d||$d->format('Y-m-d')!==$day)$day=date('Y-m-d');$start=$day.' 00:00:00';$end=date('Y-m-d',strtotime($day.' +1 day')).' 00:00:00';$s=q("SELECT COUNT(*) n,COALESCE(SUM(status='Completed'),0) done,COALESCE(SUM(status='Cancelled'),0) cancelled,COALESCE(SUM(CASE WHEN status='Completed' THEN total ELSE 0 END),0) revenue FROM orders WHERE created_at>=? AND created_at<?",[$start,$end])->fetch();?>
<span class="eyebrow">OWNER REPORT</span><h1>Daily sales</h1><form method="get" class="inline"><input type="hidden" name="page" value="sales"><input type="date" name="day" value="<?=h($day)?>" required style="width:190px"><button>View report</button></form><p class="muted">Orders placed on <?=h($day)?> (IST). Revenue counts completed orders only, not pending or cancelled orders.</p><div class="stats"><?php foreach(['Orders placed'=>$s['n'],'Completed'=>$s['done'],'Cancelled'=>$s['cancelled'],'Completed revenue'=>cash($s['revenue'])]as$k=>$v):?><div class="stat"><?=h($k)?><b><?=h($v)?></b></div><?php endforeach;?></div><div class="panel"><h2>Completed item sales</h2><table><tr><th>Item (order snapshot)</th><th>Quantity sold</th><th>Revenue</th></tr><?php $sales=q("SELECT oi.item_name,SUM(oi.quantity) qty,SUM(oi.quantity*oi.unit_price) revenue FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status='Completed' AND o.created_at>=? AND o.created_at<? GROUP BY oi.item_name ORDER BY revenue DESC",[$start,$end])->fetchAll();foreach($sales as$r):?><tr><td><?=h($r['item_name'])?></td><td><?=$r['qty']?></td><td><?=cash($r['revenue'])?></td></tr><?php endforeach;if(!$sales):?><tr><td colspan="3">No completed orders for this date.</td></tr><?php endif;?></table></div>
<?php elseif($page==='database'):?><span class="eyebrow">LIVE MYSQL DATA</span><h1>Saved beyond the browser.</h1><p class="muted">Counts and records below are read directly from MySQL, not browser storage. Database: <b>street_food_online</b>.</p><div class="panel"><h2>Relational tables</h2><table><tr><th>Table</th><th>Purpose</th><th>Rows in MySQL</th></tr><?php foreach(['admins'=>'Owner login (hashed password)','categories'=>'Menu categories','menu_items'=>'Shop menu and prices','customers'=>'Customers, unique by phone','orders'=>'Order header, status and customer snapshot','order_items'=>'Items, quantities and price snapshots']as$t=>$v):?><tr><td><b><?=$t?></b></td><td><?=h($v)?></td><td><?=q("SELECT COUNT(*) FROM `$t`")->fetchColumn()?></td></tr><?php endforeach;?></table></div><div class="panel" style="margin-top:20px"><h2>Latest saved order rows</h2><div class="table-wrap"><table><tr><th>ID / code</th><th>Customer FK</th><th>Item rows</th><th>Status</th><th>Total</th></tr><?php foreach(q('SELECT o.*, (SELECT COUNT(*) FROM order_items oi WHERE oi.order_id=o.id) item_rows FROM orders o ORDER BY o.id DESC LIMIT 5')->fetchAll()as$r):?><tr><td><?=$r['id']?> / <?=h($r['order_code'])?></td><td><?=$r['customer_id']?></td><td><?=$r['item_rows']?></td><td><?=h($r['status'])?></td><td><?=cash($r['total'])?></td></tr><?php endforeach;?></table></div><p class="muted">Foreign keys: categories → menu_items; customers → orders; orders → order_items; menu_items → order_items.</p><details><summary>View table creation SQL</summary><pre><?=h($schema)?></pre></details></div><?php endif;?>
<?php else:?><div class="panel"><h1>Page not found</h1><a href="?page=menu">Return to menu</a></div><?php endif;?>
</main><footer>Street Food Online Ordering System · PHP + MySQL · Local DBMS project demonstration</footer></body></html>
